import audioop
import base64
import os
from typing import Any, AsyncIterator, List, Optional
from urllib.parse import urlencode

import aiohttp
import structlog
from aiohttp import ClientTimeout, ClientWSTimeout

from rasa.core.channels.voice_stream.audio_bytes import (
    L16_16KHZ,
    L16_24KHZ,
    L16_48KHZ,
    MULAW_8KHZ,
    AudioFormat,
    RasaAudioBytes,
)
from rasa.core.channels.voice_stream.tts._client_session import (
    create_ssl_client_session,
)
from rasa.core.channels.voice_stream.tts.tts_engine import (
    TTSEngine,
    TTSEngineConfig,
    TTSError,
    TTSLanguageMapEntry,
    TTSStreamEvent,
    TTSWordTimestamps,
)
from rasa.shared.constants import RIME_API_KEY_ENV_VAR
from rasa.shared.exceptions import ConnectionException
from rasa.tracing import voice as voice_tracing

structlogger = structlog.get_logger()

"""
Rime TTS engine implementation.
Docs: https://docs.rime.ai/api-reference/endpoint/websockets-json#variable-parameters
"""


class RimeTTSConfig(TTSEngineConfig):
    """Rime TTS variable parameters.

    See get_default_config() for default values.
    """

    # Rime TTS calls "voice" as "speaker"
    # the voice used for synthesis
    speaker: Optional[str] = None

    # Model ID to be used for synthesis
    model_id: Optional[str] = None

    # The Rime TTS API endpoint URL
    endpoint: Optional[str] = None

    # Adjusts the speed of speech.
    speed_alpha: Optional[float] = None

    # Controls how text is segmented for synthesis.
    segment: Optional[str] = None

    # Skips text normalization of the input text prior to synthesizing
    # audio. This will reduce latency at the cost of some possible
    # mispronunciation of digits and abbreviations.
    no_text_normalization: Optional[bool] = None


class RimeTTS(TTSEngine[RimeTTSConfig]):
    required_env_vars = (RIME_API_KEY_ENV_VAR,)
    ws: Optional[aiohttp.ClientWebSocketResponse] = None
    streaming_input: bool = True

    @classmethod
    def name(cls) -> str:
        """Return the name identifier for this TTS engine."""
        return "rime"

    def __init__(
        self,
        rasa_language: str,
        format: AudioFormat,
        config: Optional[RimeTTSConfig] = None,
        additional_languages: Optional[List[str]] = None,
    ):
        if format == L16_48KHZ:
            structlogger.warning(
                "rime_tts.audio_format_sample_rate",
                message="RimeTTS does not support 48KHz sample rate. "
                "Rime will produce 24KHz audio which we upscale to 48KHz.",
            )

        super().__init__(rasa_language, format, config, additional_languages or [])
        self.session: Optional[aiohttp.ClientSession] = None
        self._reset_resampler()

    def _reset_resampler(self) -> None:
        self._resample_remainder = b""
        self._resample_state: Any = None

    def get_websocket_url(self) -> str:
        """Build WebSocket URL with query parameters for Rime TTS."""
        base_url = self.config.endpoint

        sample_rate = self.audio_format.sample_rate

        if self.audio_format in (L16_16KHZ, L16_24KHZ):
            encoding = "pcm"
        # we will transcode audio from 44100 to 48000 when we receive it
        elif self.audio_format is L16_48KHZ:
            sample_rate = 24000
            encoding = "pcm"
        elif self.audio_format is MULAW_8KHZ:
            encoding = "mulaw"
        else:
            # TODO: log a warning and transcode instead.
            raise TTSError(
                f"Unsupported audio format: {self.audio_format}. Rime does not "
                "support sample rates above 44.1kHz."
            )

        query_params = {
            "speaker": self.current_language_config.voice,
            "modelId": self.config.model_id,
            "lang": self.current_language_config.engine_language_key,
            "audioFormat": encoding,
            "samplingRate": sample_rate,
        }

        # Add optional parameters
        if self.config.speed_alpha is not None:
            query_params["speedAlpha"] = str(self.config.speed_alpha)

        if self.config.segment is not None:
            query_params["segment"] = self.config.segment

        if self.config.no_text_normalization:
            query_params["noTextNormalization"] = "true"

        url = f"{base_url}?{urlencode(query_params)}"
        return url

    @staticmethod
    def get_request_headers() -> dict[str, str]:
        """Get headers for WebSocket connection."""
        rime_api_key = os.environ[RIME_API_KEY_ENV_VAR]
        return {
            "Authorization": f"Bearer {rime_api_key}",
        }

    @voice_tracing.traced_tts_connect
    async def connect(self, config: Optional[RimeTTSConfig] = None) -> None:
        """Establish WebSocket connection to Rime TTS."""
        if self.session is None or self.session.closed:
            timeout = ClientTimeout(total=self.config.timeout)
            self.session = create_ssl_client_session(timeout)

        headers = self.get_request_headers()
        ws_url = self.get_websocket_url()

        try:
            self.ws = await self.session.ws_connect(
                ws_url,
                headers=headers,
                timeout=ClientWSTimeout(
                    ws_close=float(self.config.timeout) if self.config.timeout else 30
                ),
            )
        except aiohttp.ClientResponseError as e:
            if e.status == 401:
                error_msg = "Authentication failed. Please check your Rime API key."
            else:
                error_msg = f"Connection to Rime TTS failed with status {e.status}"
            structlogger.error(
                "rime.connection.failed",
                status_code=e.status,
                error=error_msg,
            )
            raise ConnectionException(error_msg) from e

    @voice_tracing.traced_tts_disconnect
    async def close_connection(self) -> None:
        """Close WebSocket connection. Session is kept alive for reuse."""
        if self.ws and not self.ws.closed:
            await self.ws.close()
            self.ws = None
        self._reset_resampler()

    async def prepare_response(self, streaming_config: Any = None) -> None:
        """Reset per-response resampling state before streaming audio."""
        self._reset_resampler()

    async def send_text_chunk(self, text: str) -> None:
        """Send text to TTS engine for continuous streaming.

        Rime accepts text messages as JSON objects with a "text" field.
        The API buffers inputs up to punctuation characters (., ?, !).
        """
        async with self._get_engine_lock():
            if not self.ws or self.ws.closed:
                raise TTSError("WebSocket connection not established")
            await self.ws.send_json(
                {"text": text, "contextId": self._active_response_id()}
            )

    async def signal_text_done(self) -> None:
        """Signal TTS engine to process any remaining buffered text.

        Rime uses the "eos" (end of stream) operation to flush remaining
        buffer and close the connection gracefully.
        """
        async with self._get_engine_lock():
            if not self.ws or self.ws.closed:
                raise TTSError("WebSocket connection not established")
            await self.ws.send_json({"operation": "flush"})

    async def signal_interrupt(self) -> None:
        """Clear the TTS engine buffer."""
        async with self._get_engine_lock():
            if not self.ws or self.ws.closed:
                return
            await self.ws.send_json({"operation": "clear"})
            structlogger.debug("rime.tts.clear")

    async def stream_audio(self) -> AsyncIterator[RasaAudioBytes]:
        """Stream audio output, discarding optional timing events."""
        async for event in self.stream_audio_events():
            if isinstance(event, RasaAudioBytes):
                yield event

    async def stream_audio_events(self) -> AsyncIterator[TTSStreamEvent]:
        """Stream audio output from the TTS engine.

        Rime returns JSON messages with different types:
        - "chunk": Contains base64-encoded audio data
        - "timestamps": Contains word-level timing information
        - "error": Error messages
        """
        if not self.ws or self.ws.closed:
            raise TTSError("WebSocket connection not established")

        received_audio_seconds = 0.0
        run_offset_seconds = 0.0
        previous_raw_end: Optional[float] = None
        try:
            async for msg in self.ws:
                data = msg.json()
                msg_type = data.get("type")
                message_context_id = data.get("contextId")
                if (
                    message_context_id is not None
                    and message_context_id != self._active_response_id()
                ):
                    continue

                if msg_type == "chunk":
                    # Audio data chunk - decode base64 and yield
                    base64_audio = data.get("data")
                    if base64_audio:
                        audio = self.engine_bytes_to_rasa_audio_bytes(base64_audio)
                        received_audio_seconds += audio.full_seconds()
                        yield audio

                elif msg_type == "done":
                    # All audio has been sent, stop streaming
                    break

                elif msg_type == "error":
                    # Error occurred
                    error_msg = data.get("message", "Unknown error")
                    structlogger.error("rime.stream_audio.error", error=error_msg)
                    raise TTSError(f"Rime TTS error: {error_msg}")

                elif msg_type == "timestamps":
                    word_timestamps = data.get("word_timestamps")
                    timestamps = (
                        TTSWordTimestamps.parse(
                            word_timestamps.get("words"),
                            word_timestamps.get("start"),
                            word_timestamps.get("end"),
                        )
                        if isinstance(word_timestamps, dict)
                        else None
                    )
                    if timestamps is None or not timestamps.timestamps:
                        continue
                    raw_start = min(
                        timestamp.start_seconds for timestamp in timestamps.timestamps
                    )
                    raw_end = max(
                        timestamp.end_seconds for timestamp in timestamps.timestamps
                    )
                    # Each synthesis measures from its own audio start, so a new
                    # run is placed after the audio already received.
                    # https://docs.rime.ai/api-reference/coda/websockets-json
                    if previous_raw_end is not None and raw_start < previous_raw_end:
                        run_offset_seconds = received_audio_seconds
                    previous_raw_end = raw_end
                    yield timestamps.shifted(run_offset_seconds)

                else:
                    structlogger.warning(
                        "rime.stream_audio.unknown_message", message=data
                    )
        except Exception as e:
            structlogger.error("rime.stream_audio.error", error=str(e))
            raise TTSError(f"Error during audio streaming: {e}")

    def transcode_audio(self, audio_bytes: bytes) -> bytes:
        if self.audio_format.sample_rate <= 24000:
            return audio_bytes

        # 16-bit audio
        input_sample_width = self.audio_format.bit_depth // 8
        # Mono
        input_channels = self.audio_format.channels
        frame_width = input_sample_width * input_channels
        pending_audio = self._resample_remainder + audio_bytes
        complete_frame_bytes = len(pending_audio) - (len(pending_audio) % frame_width)

        if complete_frame_bytes == 0:
            self._resample_remainder = pending_audio
            return b""

        audio_to_resample = pending_audio[:complete_frame_bytes]
        self._resample_remainder = pending_audio[complete_frame_bytes:]
        # Input sample rate, it is fixed to 24000 for L16_48KHz as temporary workaround
        input_rate = 24000
        # Desired output sample rate
        output_rate = self.audio_format.sample_rate

        converted_audio, self._resample_state = audioop.ratecv(
            audio_to_resample,
            input_sample_width,
            input_channels,
            input_rate,
            output_rate,
            self._resample_state,
        )

        return converted_audio

    async def synthesize(
        self, text: str, config: Optional[RimeTTSConfig] = None
    ) -> AsyncIterator[RasaAudioBytes]:
        """Generate speech from text using a remote TTS system."""
        if not self.ws or self.ws.closed:
            raise TTSError("WebSocket connection not established")

        response = await self.start_response()
        await response.write(text)
        await response.finish()
        async for audio_chunk in response:
            yield audio_chunk

    def engine_bytes_to_rasa_audio_bytes(self, chunk: bytes) -> RasaAudioBytes:
        """Convert the generated TTS audio bytes into rasa audio bytes."""
        audio_bytes = self.transcode_audio(base64.b64decode(chunk))
        return RasaAudioBytes(audio_bytes, format=self.audio_format)

    @staticmethod
    def get_default_config(rasa_language: str) -> RimeTTSConfig:
        return RimeTTSConfig(
            model_id="coda",
            timeout=30,
            endpoint="wss://users-ws.rime.ai/ws3",
            speed_alpha=1.0,
            segment="immediate",  # Synthesize immediately for low latency
            no_text_normalization=False,
            language_map={
                rasa_language: TTSLanguageMapEntry(
                    language="en",
                    voice="astra",
                ),
            },
        )

    @classmethod
    def from_config_dict(
        cls,
        config: Any,
        format: AudioFormat,
        rasa_language: str,
        additional_languages: Optional[List[str]] = None,
    ) -> "RimeTTS":
        return cls(
            rasa_language=rasa_language,
            format=format,
            config=RimeTTSConfig.model_validate(config),
            additional_languages=additional_languages,
        )

    async def set_language(self, rasa_language: str) -> bool:
        """Update the TTS language for next synthesis."""
        if not await super().set_language(rasa_language):
            return False
        # Recycle the websocket under the engine lock so concurrent writers
        # don't observe a half-closed connection.
        await self._reconnect_with_lock()
        return True
